import * as THREE from 'three';
import { createScene } from '/root/data/object.js';
import fs from 'fs';

// Create the scene
const scene = createScene();

// Apply -90 degree X-rotation for Blender Z-up coordinate system
const blenderTransform = new THREE.Matrix4();
blenderTransform.makeRotationX(-Math.PI / 2);
scene.applyMatrix4(blenderTransform);
scene.updateMatrixWorld(true);

// Collections for OBJ data
const vertices = [];
const faces = [];
let vertexOffset = 1; // OBJ indices start at 1

// Helper function to add geometry to OBJ data
function addGeometryToOBJ(geometry, worldMatrix, objectName) {
  const positionAttribute = geometry.attributes.position;
  const indexAttribute = geometry.index;

  const localVertices = [];
  const vertex = new THREE.Vector3();

  // Transform vertices to world space
  for (let i = 0; i < positionAttribute.count; i++) {
    vertex.fromBufferAttribute(positionAttribute, i);
    vertex.applyMatrix4(worldMatrix);
    vertices.push(`v ${vertex.x} ${vertex.y} ${vertex.z}`);
    localVertices.push(vertexOffset + i);
  }

  // Add faces
  if (indexAttribute) {
    // Indexed geometry
    for (let i = 0; i < indexAttribute.count; i += 3) {
      const a = indexAttribute.getX(i) + vertexOffset;
      const b = indexAttribute.getX(i + 1) + vertexOffset;
      const c = indexAttribute.getX(i + 2) + vertexOffset;
      faces.push(`f ${a} ${b} ${c}`);
    }
  } else {
    // Non-indexed geometry
    for (let i = 0; i < positionAttribute.count; i += 3) {
      const a = vertexOffset + i;
      const b = vertexOffset + i + 1;
      const c = vertexOffset + i + 2;
      faces.push(`f ${a} ${b} ${c}`);
    }
  }

  vertexOffset += positionAttribute.count;
}

// Traverse the scene and process all meshes
scene.traverse((object) => {
  if (object.isMesh) {
    const geometry = object.geometry;
    const worldMatrix = object.matrixWorld;

    addGeometryToOBJ(geometry, worldMatrix, object.name);
  } else if (object.isInstancedMesh) {
    // Handle instanced meshes
    const geometry = object.geometry;
    const instanceMatrix = new THREE.Matrix4();
    const worldMatrix = object.matrixWorld;
    const combinedMatrix = new THREE.Matrix4();

    for (let i = 0; i < object.count; i++) {
      object.getMatrixAt(i, instanceMatrix);
      combinedMatrix.multiplyMatrices(worldMatrix, instanceMatrix);
      addGeometryToOBJ(geometry, combinedMatrix, `${object.name}_instance_${i}`);
    }
  }
});

